742	/// (0.2.4, F89-2) Claim `rec_dir` for a spawn under the task admission lock: refuse if any OTHER
743	/// run of the task is live, or if THIS record is already live under a different process (a
744	/// concurrent resume). Then write it `running` with this process's pid + start time and `attempt`,
745	/// durably, BEFORE the caller spawns. The lock is released on return (the live owning record is
746	/// the exclusion for the run's duration).
747	fn claim_for_spawn(work_root: &Path, rec_dir: &Path, attempt: i64) -> Result<RunRecord, String> {
748	    let _lock = record::admission_lock(work_root)?;
749	    if let Some(other) = record::other_live_run(work_root, rec_dir) {
750	        return Err(format!("task already has a live work run ({other})"));
751	    }
752	    let mut rec = read_record(rec_dir)?
753	        .ok_or_else(|| "the work record vanished before it could be claimed".to_string())?;
754	    let (pid, start) = record::self_owner();
755	    if record::is_pending(&rec.status) && record::is_live(&rec) && rec.pid != Some(pid) {
756	        return Err(format!(
757	            "work run {} is already live under pid {}; refusing a second launch",
758	            rec.id,
759	            rec.pid.unwrap_or(0)
760	        ));
761	    }
762	    rec.status = "running".into();
763	    rec.pid = Some(pid);
764	    rec.pid_start = start;
765	    rec.attempt = attempt;
766	    rec.ended = None;
767	    rec.error = String::new();
768	    rec.args = None;
769	    write_record(rec_dir, &rec)?;
770	    Ok(rec)
771	}
