825	/// A fresh [`Quota`] block: `resume_at` = `reset_at` + 60 s when the provider gave a reset time,
826	/// else now + the quota window.
827	fn build_quota(
828	    quota_text: &str,
829	    reset_at: Option<DateTime<Utc>>,
830	    window_sec: i64,
831	    resumes: i64,
832	    exhausted: bool,
833	) -> Quota {
834	    let resume_at = match reset_at {
835	        Some(r) => r + chrono::Duration::seconds(60),
836	        None => Utc::now() + chrono::Duration::seconds(window_sec.max(60)),
837	    };
838	    Quota {
839	        text: quota_text.to_string(),
840	        reset_at: reset_at.map(|r| r.to_rfc3339()),
841	        resume_at: resume_at.to_rfc3339(),
842	        resumes,
843	        exhausted,
844	    }
845	}
